class Solution {
private:
    void merge_helper(vector<int>& nums, int start, int mid, int end){
        // pointers, indicating startig of both the halves
        int i = start;
        int j = mid + 1;
        vector<int> temp; // to store sorted values

        while(i <= mid && j <= end){
            if(nums[i] < nums[j]){
                temp.push_back(nums[i]);
                i++;
            } 
            else{
                temp.push_back(nums[j]);
                j++;
            }
        }

        // remainig leftovers in left half
        while(i<=mid){
            temp.push_back(nums[i]);
            i++;
        }

        // remainig leftovers in right half
        while(j<=end){
            temp.push_back(nums[j]);
            j++;
        }

        // copying to original array
        for(int idx = 0; idx < temp.size(); idx++){
    nums[idx + start] = temp[idx];
}
    }

    void sort_helper(vector<int>& nums, int start, int end){
        int mid = start + ((end - start) / 2);

        // all in base case
        if(start < end){
            // left half call
            sort_helper(nums, start, mid);

            // right half call
            sort_helper(nums, mid + 1, end);

            // merge call
            merge_helper(nums, start, mid, end);
        }
    }
public:
    vector<int> mergeSort(vector<int>& nums) {
        sort_helper(nums, 0, nums.size() - 1);
        return nums;
    }
};

```

