func merge(_ arr: inout [Int], _ low: Int, _ mid: Int, _ high: Int) {
    var temp: [Int] = []
    var left = low
    var right = mid + 1

    while left <= mid && right <= high {
        if arr[left] <= arr[right] {
            temp.append(arr[left])
            left += 1
        } else {
            temp.append(arr[right])
            right += 1
        }
    }

    while left <= mid {
        temp.append(arr[left])
        left += 1
    }

    while right <= high {
        temp.append(arr[right])
        right += 1
    }

    for i in 0..<temp.count {
        arr[low + i] = temp[i]
    }
}

